      "path": "package.json",
      "content": "{\n  \"name\": \"no-ai-style\",\n  \"version\": \"1.2.2\",\n  \"description\": \"Academic and professional prose editing for DeepSeek Harness: a skill that removes mechanical AI phrasing, defensive hedging and filler while protecting claims, citations, statistics, methodology and limitations, plus a composer button that inserts one of its three modes into the input box.\",\n  \"type\": \"module\",\n  \"main\": \"index.js\",\n  \"exports\": {\n    \".\": \"./index.js\",\n    \"./client\": \"./lib/client.js\",\n    \"./package.json\": \"./package.json\",\n    \"./locale/*.json\": \"./locale/*.json\"\n  },\n  \"files\": [\n    \"index.js\",\n    \"lib/\",\n    \"cordis.patch.yml\",\n    \"skills/\",\n    \"locale/\",\n    \"docs/\",\n    \"README.md\",\n    \"README.zh-CN.md\",\n    \"README.ja.md\",\n    \"LICENSE\"\n  ],\n  \"dsh\": {\n    \"bundle\": {\n      \"patch\": \"./cordis.patch.yml\"\n    },\n    \"client\": {\n      \"platform\": \"web\",\n      \"immediately\": true,\n      \"inject\": [\n        \"@deepseek-ai/dsh-client-locale\",\n        \"@deepseek-ai/dsh-client-ui-conversation\",\n        \"@deepseek-ai/dsh-client-ui-slots\",\n        \"react\",\n        \"react-dom\"\n      ]\n    }\n  },\n  \"keywords\": [\n    \"dsh-plugin\",\n    \"deepseek-harness\",\n    \"skill\",\n    \"writing\",\n    \"academic-writing\",\n    \"prose-editing\",\n    \"humanize\",\n    \"anti-ai\",\n    \"去ai味\",\n    \"论文润色\",\n    \"写作润色\",\n    \"日本語文章校正\"\n  ],\n  \"repository\": {\n    \"type\": \"git\",\n    \"url\": \"git+https://github.com/01NGVI-QINGYI/no-ai-style.git\"\n  },\n  \"license\": \"MIT\",\n  \"author\": \"01NGVI-QINGYI\",\n  \"peerDependencies\": {\n    \"@deepseek-ai/dsh-skill-filesystem\": \">=0.1.0-rc.6 <0.3.0\",\n    \"react\": \"^18.2.0\",\n    \"react-dom\": \"^18.2.0\"\n  },\n  \"peerDependenciesMeta\": {\n    \"react\": {\n      \"optional\": true\n    },\n    \"react-dom\": {\n      \"optional\": true\n    }\n  }\n}\n"
